#!/usr/bin/env python3
"""Consigne les lectures effectuées. Ne lit ni ne signe à la place de l'auteur."""
from pathlib import Path
import json, hashlib, datetime
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[4]
CACHE=Path('/workspace/medina-source-cache/C92')
R=OUT/'recherche_C92'; R.mkdir(exist_ok=True)
NOW=datetime.datetime.now(datetime.timezone.utc).isoformat()
OLD=json.loads(Path('/workspace/Medina-hematologie-C95/docs/collaboration/ssp-v2/execution/ALPHA77-CODEX-C95-INTEGRATE/recherche_C95/sources.json').read_text())['sources']
S=[]
def add(n,key,url,title,editor,version,section,fact,population,limits,file,depth='section'):
 p=Path(file) if str(file).startswith('/') else CACHE/file
 S.append(dict(id=f'S{n}',key=key,url=url,titre=title,editeur=editor,version_annee=version,date_consultation='2026-11-02',recorded_at=NOW,section_page=section,passage_paraphrase=fact,population=population,limites=limits,niveau_lecture=depth,cache_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),read_in_current_session=True))
def reuse(n,key,oldkey,extra=None):
 x=dict(next(r for r in OLD if r['key']==oldkey));x.update(id=f'S{n}',key=key,reuse_attributed='Lecture réelle du même parent pendant C85/C86/C95, conservée avec sa portée ; aucune nouvelle lecture intégrale revendiquée pour C92.')
 if extra:x['section_page']+=' ; nouvelle lecture C92 : '+extra;x['read_in_current_session']=True
 S.append(x)
